nextflow_process {

    name "Test Process VCFTOOLS"
    script "../main.nf"
    process "VCFTOOLS"

    tag "modules"
    tag "modules_nfcore"
    tag "vcftools"
    config "./nextflow.config"

    test("sarscov2 - vcf") {

        when {
            params {
                module_args = '--freq'
            }
            process {
                """
                input[0] = [
                    [ id:'test' ], // meta map
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/vcf/test.vcf', checkIfExists: true)
                ]
                // bed
                input[1] = []
                // diff_variant_file
                input[2] = []
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }

    }

    test("sarscov2 - vcfgz") {

